package org.mockito.internal.matchers;

import java.io.*;
import java.lang.reflect.Array;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Equality_areEqual_TriageGen2Test {

    @Test
    public void testAreEqual_BothNull() {
        assertTrue(Equality.areEqual(null, null));
    }

    @Test
    public void testAreEqual_FirstNull() {
        assertFalse(Equality.areEqual(null, new Object()));
    }

    @Test
    public void testAreEqual_SecondNull() {
        assertFalse(Equality.areEqual(new Object(), null));
    }

    @Test
    public void testAreEqual_BothArraysEqual() {
        // Note: isArray and areArraysEqual are internal/private logic 
        // but we test the branch via standard Object arrays
        Integer[] arr1 = {1, 2, 3};
        Integer[] arr2 = {1, 2, 3};
        assertTrue(Equality.areEqual(arr1, arr2));
    }

    @Test
    public void testAreEqual_FirstIsArraySecondIsNot() {
        Integer[] arr = {1, 2, 3};
        Object obj = new Object();
        // isArray(o1) is true, isArray(o2) is false -> returns false
        assertFalse(Equality.areEqual(arr, obj));
    }

    @Test
    public void testAreEqual_SecondIsArrayFirstIsNot() {
        Object obj = new Object();
        Integer[] arr = {1, 2, 3};
        // isArray(o1) is false -> goes to else branch
        // obj.equals(arr) is false
        assertFalse(Equality.areEqual(obj, arr));
    }

    @Test
    public void testAreEqual_ArraysNotEqual() {
        Integer[] arr1 = {1, 2, 3};
        Integer[] arr2 = {3, 2, 1};
        assertFalse(Equality.areEqual(arr1, arr2));
    }

    @Test
    public void testAreEqual_StandardObjectsEqual() {
        String s1 = "test";
        String s2 = "test";
        assertTrue(Equality.areEqual(s1, s2));
    }

    @Test
    public void testAreEqual_StandardObjectsNotEqual() {
        String s1 = "test";
        String s2 = "different";
        assertFalse(Equality.areEqual(s1, s2));
    }

    @Test
    public void testAreEqual_DifferentTypes() {
        Integer i = 1;
        String s = "1";
        assertFalse(Equality.areEqual(i, s));
    }
}
